            print("ECE", eval_ece)
            print('--------- ECE stat ----------', epoch)
            print("ACC", acc_bin)
            print("Conf", conf_bin)
            print("Bm", Bm_bin)

        if args.lr_schedule in ['cosine']:
            scheduler.step()
        elif args.lr_schedule in ['plateau']:
            scheduler.step(sum(loss_test))
        else:
            scheduler(epoch)

        if (epoch + 1) % 10 == 0 and args.log_dir:
